#include <bits/stdc++.h>
using namespace std;

int invnum(const std::vector<int>& seq) {
    int count = 0;
    int len = seq.size();
    for (int i = 0; i < len; ++i) {
        for (int j = i + 1; j < len; ++j) {
            if (seq[i] > seq[j]) {
                count++;
            }
        }
    }
    return count;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, mod;
    cin >> n >> mod;

    // Initialize memo_table: 3D vector of unordered_map<int, long long>
    // Dimensions: 2 x (n+1) x (2*max_inv+1)
    // Since k can be negative, we offset indices by max_inv
    int max_inv = n * (n - 1) / 2;
    int offset = max_inv + 1; // to handle negative k
    // Using vector of vector of unordered_map for memoization
    std::vector<std::vector<std::unordered_map<int, long long>>> memo_table(2, std::vector<std::unordered_map<int, long long>>(n + 1));

    // Recursive function with memoization
    std::function<long long(int, int, bool)> solve = [&](int N, int K, bool flag) -> long long {
        int k_idx = K;
        if (memo_table[flag][N].count(k_idx)) {
            return memo_table[flag][N][k_idx];
        }
        if (N == 1) {
            long long res = 0;
            if (!flag) {
                res = (K < 0) ? 1 : 0;
            } else {
                res = 0;
            }
            memo_table[flag][N][k_idx] = res;
            return res;
        }
        int max_inv_local = N * (N - 1) / 2;
        if (K < -max_inv_local - 1) {
            long long res = solve(N, -max_inv_local - 1, flag);
            memo_table[flag][N][k_idx] = res;
            return res;
        }
        if (K >= max_inv_local) {
            memo_table[flag][N][k_idx] = 0;
            return 0;
        }
        long long total = 0;
        for (int delta = -N + 1; delta < N; ++delta) {
            if (flag && delta > 0) continue;
            int weight = std::min(N - delta, delta + N);
            total += solve(N - 1, K - delta, flag && delta == 0) * weight;
            total %= mod;
        }
        memo_table[flag][N][k_idx] = total;
        return total;
    };

    long long result = solve(n, 0, true) % mod;
    cout << result << "\n";

    return 0;
}
